export function playerNameScriptFor(codePoint) {
  if (!Number.isInteger(codePoint)) return -1;
  let low = 0;
  let high = PLAYER_NAME_SCRIPT_RANGES.length - 1;
  while (low <= high) {
    const middle = (low + high) >>> 1;
    const [start, end, script] = PLAYER_NAME_SCRIPT_RANGES[middle];
    if (codePoint < start) high = middle - 1;
    else if (codePoint > end) low = middle + 1;
    else return script;
  }
  return -1;
}
